    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    pair_count = b_idx.numel()
    if pair_count <= 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamped_weights_reweight_only'})
    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    beta = float(extra.get('weight_beta', 1.0))
    weight_raw = gap * beta
    weight = weight_raw.clamp(min=0.05, max=10.0)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamped_weights_reweight_only'})

def generated_builder(feature_cache, extra):
