    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'uniform_none', 'constraint_family': 'clamped_weights_reweight_only'})
